{"code": "import pandas as pd
from datetime import datetime, timedelta

df = pd.read_excel('DuLieuBanHang.xlsx', sheet_name='DanhSachHoaDon')

# Parse time column: mix of serial int (Excel) and 'dd/mm/yyyy' strings
def parse_time(v):
    if isinstance(v, (int,)):
        base = datetime(1899,12,30)
        return (base + timedelta(days=int(v))).date()
    s = str(v).strip()
    for fmt in ('%d/%m/%Y','%Y-%m-%d'):
        try:
            return datetime.strptime(s, fmt).date()
        except: pass
    return pd.NaT
df['_d'] = df['Thời gian'].apply(parse_time)
print("Date range:", df['_d'].min(), "->", df['_d'].max())
print("June 2025 order count:", ((df['_d']>=pd.Timestamp('2025-06-01'))&(df['_d']<=pd.Timestamp('2025-06-30'))).sum())

# Parse numeric columns
def pv(x):
    if x is None: return None
    s=str(x).replace('.','').replace(',','').replace(' ','')
    try: return int(s)
    except: 
        try: return float(s)
        except: return None
for c in ['Tổng tiền hàng','Giảm giá','Tổng sau giảm giá','Khách đã trả']:
    df[c] = df[c].apply(pv)

print("\n=== Status x Payment method ===")
for s in sorted(df['Trạng thái'].dropna().unique()):
    sub = df[df['Trạng thái']==s]
    print(f"\n[{s}] count={len(sub)}")
    print("  Phương thức:", sub['Phương thức thanh toán'].value_counts().to_dict())
    print("  Khách đã trả median:", sub['Khách đã trả'].median())
    print("  Tổng sau giảm giá median:", sub['Tổng sau giảm giá'].median())
    print("  Thời gian tạo sample:", sub['Thời gian tạo'].head(3).tolist())
"}

